import { fmt, indicator } from './core.js';
export function svg(body,label,id='scene',height=420){
 return `<svg viewBox="0 0 760 ${height}" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${id}-wall" x2="0" y2="1"><stop stop-color="#e4eadd"/><stop offset="1" stop-color="#f6f2e5"/></linearGradient><linearGradient id="${id}-glass"><stop stop-color="#effcfa" stop-opacity=".7"/><stop offset=".4" stop-color="#ffffff" stop-opacity=".08"/><stop offset="1" stop-color="#c2d6ce" stop-opacity=".5"/></linearGradient><linearGradient id="${id}-metal"><stop stop-color="#647873"/><stop offset=".4" stop-color="#e8efea"/><stop offset="1" stop-color="#84968e"/></linearGradient><filter id="${id}-shadow"><feDropShadow dx="0" dy="6" stdDeviation="8" flood-opacity=".12"/></filter></defs><rect width="760" height="${height}" rx="14" fill="url(#${id}-wall)"/><path d="M0 ${height-75}H760V${height}H0Z" fill="#d6c7a9"/><path d="M0 ${height-75}H760" stroke="#b9ab90" stroke-width="3"/><path d="M0 ${height-70}H760" stroke="#f4ead6" stroke-width="2"/><path d="M32 ${height-44}H728M46 ${height-21}H711" stroke="#bdab8a" opacity=".2"/>${body}</svg>`;
}
export function label(x,y,t,size=15,color='#365344',anchor='middle'){return `<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-size="${size}" font-family="Microsoft JhengHei,system-ui,sans-serif">${t}</text>`;}
export function beaker(id,x=235,y=150,w=230,h=195,color='#a9c9b5',fill=.62,solid=0){
 const ly=y+h*(1-fill),marks=[.25,.5,.75].map(n=>`<path d="M${x+12} ${y+h*n}h20" stroke="#64877b" opacity=".6"/>`).join('');
 let crystals='';for(let i=0;i<Math.min(34,Math.ceil(solid*2));i++)crystals+=`<rect x="${x+20+(i*29)%(w-42)}" y="${y+h-12-Math.floor(i/7)*8}" width="8" height="8" rx="1" fill="#fffdf3" stroke="#c6c9bd" transform="rotate(${i*17%60} ${x+20+(i*29)%(w-42)} ${y+h-12-Math.floor(i/7)*8})"/>`;
 return `<ellipse cx="${x+w/2}" cy="${y+h+10}" rx="${w*.63}" ry="14" fill="#61715a20"/><path d="M${x} ${ly}H${x+w}V${y+h-8}Q${x+w} ${y+h} ${x+w-10} ${y+h}H${x+10}Q${x} ${y+h} ${x} ${y+h-8}Z" fill="${color}" opacity=".65"/><ellipse cx="${x+w/2}" cy="${ly}" rx="${w/2}" ry="5" fill="${color}" opacity=".7"/><path d="M${x-9} ${y-7}L${x+3} ${y+5}V${y+h-9}Q${x+3} ${y+h+3} ${x+16} ${y+h+3}H${x+w-12}Q${x+w} ${y+h+3} ${x+w} ${y+h-9}V${y}" fill="url(#${id}-glass)" stroke="#73988c" stroke-width="3"/><path d="M${x+14} ${y+12}V${y+h-18}" stroke="white" stroke-opacity=".7" stroke-width="5"/><path d="M${x+3} ${y+5}Q${x+w*.5} ${y-6} ${x+w} ${y}" stroke="#d8e9e0" stroke-width="1.5" fill="none"/><path d="M${x+w-10} ${y+16}V${y+h-20}" stroke="#f7fffa" stroke-opacity=".5" stroke-width="2"/>${marks}${crystals}`;
}
export function ionsView(ions,{solid=false,on=false,id='ions',neutral=''}={}){
 let rows=ions.filter(i=>i.c>1e-6); if(!rows.length&&ions.length)rows=ions.filter(i=>i.key==='H'||i.key==='OH');
 let body=`<rect x="35" y="48" width="690" height="245" rx="15" fill="#f9fbf4" stroke="#c9d5c2"/><rect x="55" y="76" width="12" height="190" rx="4" fill="#6d92b5"/><rect x="693" y="76" width="12" height="190" rx="4" fill="#bb7565"/>${label(60,36,'− 負電極',13)}${label(697,36,'＋ 正電極',13)}`;
 if(solid){for(let i=0;i<24;i++){const x=220+(i%6)*58,y=106+Math.floor(i/6)*47;body+=`<circle cx="${x}" cy="${y}" r="20" fill="${(i+Math.floor(i/6))%2?'#93b7bd':'#dba77f'}"/>${label(x,y+5,(i+Math.floor(i/6))%2?'Cl⁻':'Na⁺',12)}`;}}
 else rows.forEach((ion,k)=>{for(let j=0;j<3;j++){const x=150+j*200+(k%2)*45,y=105+(k%4)*47;body+=`<g class="${on?'ion-drift':''}" style="--dx:${ion.charge>0?-60:60}px;--duration:${8/(ion.mobility||1)}s;animation-delay:-${j}s"><circle cx="${x}" cy="${y}" r="${ion.label.length>4?27:20}" fill="${ion.charge>0?'#e8b68b':'#a4cbd1'}" stroke="#fff"/>${label(x,y+4,ion.label,ion.label.length>4?10:13)}</g>`;}});
 if(neutral){for(let j=0;j<3;j++)body+='<g><ellipse cx="'+(235+j*142)+'" cy="226" rx="55" ry="18" fill="#e7debe"/>'+label(235+j*142,230,neutral.includes('糖')?'糖分子':'CH₃COOH',12)+'</g>';body+=label(380,270,neutral,13);}
 body+=label(380,327,solid?'晶格中的離子位置受限':on?'陽離子 ← 負極　｜　正極 → 陰離子':'電場關閉：粒子仍有熱運動，無定向漂移',14);
 return svg(body,'微觀離子與電極示意',id,360);
}
export function conductScene(s,{loaded=false,immersed=false,powered=false,id='conduct'}={}){
 const angle=-70+s.score*1.4, needleX=151+61*Math.sin(angle*Math.PI/180),needleY=139-61*Math.cos(angle*Math.PI/180);
 const body=`<rect x="45" y="47" width="216" height="130" rx="15" fill="#f7f4e8" stroke="#b3b5a2" filter="url(#${id}-shadow)"/><path d="M80 133A72 72 0 0 1 222 133" fill="none" stroke="#bcc8b0" stroke-width="12"/><path d="M151 139L${needleX} ${needleY}" stroke="#ac674d" stroke-width="3"/><circle cx="151" cy="139" r="6" fill="#566b55"/>${label(151,78,'導電比較計',14)}${label(151,164,fmt(s.score,3)+' / 100',15)}<rect x="560" y="56" width="133" height="76" rx="10" fill="#526956"/>${label(626,83,'低電壓檢測',12,'#f5f2df')}${label(626,111,powered?'ON':'OFF',21,'#fff3bd')}<path d="M260 121Q330 102 321 190M560 111Q489 97 431 190" fill="none" stroke="#796753" stroke-width="5"/><circle cx="482" cy="92" r="19" fill="${s.score>.1?'#f2d06a':'#a9b3a0'}" opacity="${.35+s.lamp*.65}"/>${beaker(id,275,190,205,160,loaded?'#b1d4c6':'#d9e3d9',loaded&&s.id!=='solid'?.66:0,loaded&&s.id==='solid'?20:0)}<g transform="translate(0 ${immersed?0:-65})"><rect x="312" y="155" width="17" height="130" rx="4" fill="url(#${id}-metal)"/><rect x="422" y="155" width="17" height="130" rx="4" fill="url(#${id}-metal)"/>${label(320,148,'−',19)}${label(431,148,'＋',19)}</g>${label(378,389,loaded?(s.id==='solid'?'固態 NaCl：離子位置固定':'樣品已放入：比較電荷如何移動'):'先點選或拖入一份樣品',15)}`;
 return svg(body,'低電壓導電實驗，讀數 '+fmt(s.score,3),id);
}
export function phScene(s,{kind='btb',dropped=false,paper=false,meter=false,id='ph'}={}){
 const ind=indicator(kind,s.pH),paperInd=indicator('universal',s.pH);
 let body=beaker(id,270,157,225,188,dropped&&!['red','blue'].includes(kind)?ind.color:'#c1d8ce',.66);
 body+=`<path d="M180 73l47 22-17 38-47-22Z" fill="#dcc8a0" stroke="#a58c62"/><path d="M169 113l36 17-7 16-31-14Z" fill="#8e9d91"/><path d="M192 146l-6 20" stroke="#95aaa2" stroke-width="5"/>${dropped?'<circle class="drop-fall" cx="184" cy="179" r="5" fill="'+ind.color+'"/>':''}${label(166,59,'指示劑',14)}<rect x="537" y="62" width="166" height="94" rx="12" fill="#446351"/><rect x="550" y="78" width="139" height="47" rx="5" fill="#edf1cc"/>${label(619,108,meter?'pH '+fmt(s.pH):'pH —',25)}${label(618,145,'25°C 參考讀值',11,'#f2f4df')}<path d="M537 111Q476 69 458 125V${meter?280:145}" fill="none" stroke="#687d70" stroke-width="5"/><rect x="447" y="${meter?209:116}" width="21" height="81" rx="6" fill="#d8e1d7" stroke="#849d8d"/><path d="M458 ${meter?266:173}v19" stroke="#394a40" stroke-width="6"/><rect x="81" y="213" width="36" height="109" rx="3" fill="#ede1c2" stroke="#b5a68a"/><rect x="81" y="271" width="36" height="51" fill="${paper?paperInd.color:'#ede1c2'}"/>${label(100,350,'pH 試紙',13)}${label(382,388,dropped?ind.label:'滴加後，觀察顏色',15)}`;
 if(dropped&&['red','blue'].includes(kind))body+=`<rect x="220" y="166" width="25" height="116" fill="${kind==='red'?'#d06b79':'#677fc5'}"/><rect x="220" y="235" width="25" height="47" fill="${ind.color}"/>`;
 return svg(body,'指示劑、試紙與 pH 計同步觀察',id);
}
export function neutralScene(s,{v=0,reverse=false,pouring=false,id='neutral'}={}){
 const col=indicator('btb',s.pH).color;
 return svg(`<path d="M110 336H229M168 337V42H380" fill="none" stroke="#8a998c" stroke-width="8"/><rect x="347" y="47" width="36" height="152" rx="5" fill="url(#${id}-glass)" stroke="#789b8d" stroke-width="2"/><rect x="352" y="${59+Math.min(v,100)}" width="26" height="${Math.max(5,125-Math.min(v,100))}" fill="#b2d2cc"/><path d="M364 199V229M350 205H381" stroke="#6c7f70" stroke-width="5"/>${[0,1,2,3,4].map(i=>'<path d="M347 '+(70+i*25)+'h12" stroke="#789b8d"/>').join('')}${label(438,89,reverse?'滴入 HCl':'滴入 NaOH',16)}${label(438,116,fmt(v)+' mL',17)}${beaker(id,267,248,202,106,col,.54)}${pouring?'<circle class="drop-fall" cx="365" cy="239" r="4" fill="#a3c4ba"/>':''}<rect x="537" y="184" width="168" height="113" rx="13" fill="#4a6251"/>${label(621,220,'pH '+fmt(s.pH),27,'#f8f4df')}${label(621,252,fmt(s.temperature)+' °C',21,'#e1dab2')}${label(621,281,'理想絕熱升溫',12,'#edf1df')}${label(375,392,s.acidLeft>1e-12?'酸過量':s.baseLeft>1e-12?'鹼過量':'酸鹼當量相等',18)}`,'滴定器與反應燒杯',id);
}
export function precipScene(s,{mixed=false,filtered=false,id='precip'}={}){
 const body=beaker(id,70,159,155,177,'#bfd7cc',mixed?0:.64)+beaker(id,280,159,155,177,mixed&&s.mass?'#edf0df':'#bdd5cb',filtered?0:.64,mixed&&!filtered?s.mass*13:0)+`<path d="M495 139H681L602 233V267H577V233Z" fill="#eff4e9" stroke="#8f9f8b" stroke-width="3"/><path d="M505 147H670L589 225Z" fill="#fffdf2"/>${filtered&&s.mass?'<ellipse cx="589" cy="175" rx="37" ry="9" fill="#d8d6bd"/>':''}${beaker(id,523,280,136,67,'#bfd7cc',filtered?.55:0)}${label(147,129,'Na₂CO₃(aq)',15)}${label(357,129,mixed?'混合後':'第二份溶液',15)}${label(589,111,filtered?'濾紙上：CaCO₃ '+fmt(s.mass,3)+' g':'濾紙與漏斗',15)}${label(147,377,mixed?'原料已移入':'反應前',13)}${label(357,377,filtered?'已倒入漏斗':mixed?'CaCO₃ '+fmt(s.mass,3)+' g':'先混合觀察',13)}${label(589,377,filtered?'濾液仍含溶解離子':'固液分離',13)}`;
 return svg(body,'混合沉澱及過濾裝置',id);
}
export function crystalScene(s,{mode='pure',filtered=false,settled=false,weather='sun',running=false,id='crystal'}={}){
 let crystals='';for(let i=0;i<Math.min(65,Math.ceil(s.crystalMass*2));i++){const x=205+(i*47)%334,y=220+(i*29)%73;crystals+=`<path d="M${x} ${y}l10-5 9 5v12l-9 5-10-5Z" fill="#fffcdf" stroke="#bbc5b4"/>`;}
 let mud='';if(s.dirtLeft)for(let i=0;i<15;i++)mud+=`<circle cx="${220+i*20}" cy="${257+(i%3)*13}" r="3" fill="#8e7655"/>`;
 const body=`${weather==='sun'?'<circle cx="639" cy="63" r="27" fill="#e6c77a"/>':'<path d="M577 75q-15-30 20-38 20-35 50 0 40-1 36 38Z" fill="#b9c9be"/>'}<path d="M0 136Q100 56 212 134T420 124T760 140V192H0Z" fill="#c7d2bc"/><path d="M109 231L265 169H618L686 282 511 352H169Z" fill="#b7aa8d" stroke="#8f8f74" stroke-width="3"/><path d="M130 233L276 183H605L664 277 505 332H185Z" fill="#c8ded3"/><path d="M159 240L285 199H592L640 275 499 314H196Z" fill="#8eb7af" opacity="${.25+.6*s.waterLeft/Math.max(1,s.waterLeft+s.evaporated)}"/>${crystals}${mud}${running?'<g class="vapor" fill="none" stroke="#f8fff3" stroke-width="3"><path d="M308 208q-20-25 0-50t0-37M389 194q-20-25 0-50t0-37M476 204q-20-25 0-50t0-37"/></g>':''}${label(215,66,mode==='pure'?'A · 純氯化鈉水溶液':'B · 天然鹵水簡化模型',18)}${label(215,95,filtered?'已過濾懸浮物':settled?'已沉降、傾取上清液':'尚未前處理',13)}${label(384,386,'剩水 '+fmt(s.waterLeft)+' g　｜　析晶 '+fmt(s.crystalMass)+' g',18)}`;
 return svg(body,'蒸發池與依質量守恆析出的晶體',id);
}
export function landscape(scene='saltfield'){
 if(scene==='saltfield')return crystalScene({waterLeft:100,evaporated:35,crystalMass:14,dirtLeft:0},{id:'hero-field'});
 if(scene==='well')return svg('<path d="M0 160Q150 60 300 164T760 140V350H0Z" fill="#c8d0b9"/><ellipse cx="380" cy="284" rx="145" ry="42" fill="#887e69"/><path d="M235 260V319Q380 370 525 319V260" fill="#c5b595" stroke="#8a8069" stroke-width="4"/><ellipse cx="380" cy="260" rx="145" ry="42" fill="#776e5c"/><ellipse cx="380" cy="264" rx="119" ry="28" fill="#8eaea3"/><path d="M255 250V80H505V250M380 80V213" fill="none" stroke="#887351" stroke-width="13"/><path d="M347 204H411L400 253H358Z" fill="#b19e7c"/>'+label(380,389,'鹽井：成分要測量，不能靠外觀',17),'古代鹽井示意','well');
 if(scene==='home')return svg('<path d="M150 300H610M215 300V370M547 300V370" fill="none" stroke="#826f50" stroke-width="14"/><ellipse cx="385" cy="238" rx="142" ry="89" fill="#c1d2cb" stroke="#7c9590" stroke-width="5"/><ellipse cx="385" cy="238" rx="87" ry="62" fill="#81b9c8"/><ellipse cx="385" cy="238" rx="57" ry="43" fill="#c5f3ef"/><path d="M320 162L342 197M451 163L429 197M319 311L342 278M452 311L429 278" stroke="#839893" stroke-width="10"/>'+label(380,71,'熟悉的時空裝置，再次亮起',22)+label(380,391,'承諾已兌現，帶著證據回家',16),'銀白機身與藍色核心的既有時空裝置','home');
 return svg('<path d="M80 103L380 33 680 103H80Z" fill="#7a8467"/><path d="M120 111H640V139H120Z" fill="#b6a27e"/><path d="M151 139V337M609 139V337" stroke="#967c59" stroke-width="32"/><path d="M218 139H542V334H218Z" fill="#d8cba8"/><path d="M237 151H523V304H237Z" fill="#566b53"/><path d="M339 268V195H421V268M327 270H433" fill="#bca26e" stroke="#dec78d" stroke-width="9"/><path d="M82 346H678M61 366H699" stroke="#b8ae94" stroke-width="17"/>'+label(380,184,'信',31,'#efe2b0')+label(380,397,'皇帝的承諾，與自願留下的最後一份幫助',16),'皇宮大殿示意','palace');
}
export function phScale(pH){return '<div class="ph-scale" aria-label="pH 色階 0 到 14"><div class="ph-colors">'+Array.from({length:15},(_,i)=>'<span style="background:'+indicator('universal',i).color+'">'+i+'</span>').join('')+'</div><i style="left:'+Math.max(0,Math.min(100,pH/14*100))+'%"></i><div class="scale-labels"><span>酸性</span><span>中性</span><span>鹼性</span></div></div>';}

